scriptBlocks:
let title = translate(templateObject?.title?.content ?? '');
            let description = translate(templateObject?.description?.content ?? '');
            let author = translate(templateObject?.author?.content ?? '');
            document.getElementById('title').innerText = title;
            document.getElementById('description').innerText = description;
            document.getElementById('author').innerText = author;
            let titleHtmlTag = document.createElement('title');
            titleHtmlTag.textContent = title;
            document.getElementsByTagName('head')[0].appendChild(titleHtmlTag);
            let descriptionMetaTag = document.createElement('meta');
            descriptionMetaTag.name = "description";
            descriptionMetaTag.content = description;
            document.getElementsByTagName('head')[0].appendChild(descriptionMetaTag);
            let authorMetaTag = document.createElement('meta');
            authorMetaTag.name = "author";
            authorMetaTag.content = author;
            document.getElementsByTagName('head')[0].appendChild(authorMetaTag);

templateHtmlPreviewer.style.width = canvas?.size?.x ?? templateHtmlPreviewer.style.width;
            templateHtmlPreviewer.style.height = canvas?.size?.y ?? templateHtmlPreviewer.style.height;
            templateHtmlPreviewer.style.minWidth = canvas?.size?.constraints?.minX ?? templateHtmlPreviewer.style.minWidth;
            templateHtmlPreviewer.style.minHeight = canvas?.size?.constraints?.minY ?? templateHtmlPreviewer.style.minHeight;
            templateHtmlPreviewer.style.maxWidth = canvas?.size?.constraints?.maxX ?? templateHtmlPreviewer.style.maxWidth;
            templateHtmlPreviewer.style.maxHeight = canvas?.size?.constraints?.maxY ?? templateHtmlPreviewer.style.maxHeight;

templateHtmlPreviewer.style.backgroundColor = screen?.background?.color ?? document.body.style.backgroundColor;
            templateHtmlPreviewer.style.borderColor = screen?.border?.color ?? document.body.style.borderColor;
            templateHtmlPreviewer.style.borderWidth = screen?.border?.width ?? document.body.style.borderWidth;

htmlElement.style.position = jsonElement.position?.type ?? 'absolute';
            htmlElement.style.left = jsonElement.position?.x ?? htmlElement.style.left;
            htmlElement.style.top = jsonElement.position?.y ?? htmlElement.style.top;
            htmlElement.style.height = jsonElement.size?.y ?? htmlElement.style.height;
            htmlElement.style.minHeight = jsonElement.size?.constraints?.minY ?? htmlElement.style.minHeight;
            htmlElement.style.maxHeight = jsonElement.size?.constraints?.maxY ?? htmlElement.style.maxHeight;
            htmlElement.style.width = jsonElement.size?.x ?? htmlElement.style.width;
            htmlElement.style.minWidth = jsonElement.size?.constraints?.minX ?? htmlElement.style.minWidth;
            htmlElement.style.maxWidth = jsonElement.size?.constraints?.maxX ?? htmlElement.style.maxWidth;
            htmlElement.style.backgroundColor = jsonElement.background?.color ?? htmlElement.style.backgroundColor;
            htmlElement.style.borderColor = jsonElement.border?.color ?? htmlElement.style.borderColor;
            htmlElement.style.borderWidth = jsonElement.border?.width ?? htmlElement.style.borderWidth;
            htmlElement.style.borderRadius = jsonElement.border?.radius ?? htmlElement.style.borderRadius;
            htmlElement.style.zIndex = jsonElement.zIndex ?? htmlElement.style.zIndex;

let buttonsJson = screen.buttons ?? [];
            for (let buttonJson of buttonsJson) {
                let buttonHtml = document.createElement('button');
                buttonHtml.addEventListener('click', () => actions[buttonJson.action?.name ?? 'doNothing'](buttonJson.action.args));
                buttonHtml.setAttribute('type', 'button');
                buttonHtml.textContent = translate(buttonJson.text?.content ?? '');
                setCommonAttributes(buttonHtml, buttonJson);
                buttonsToRemove.push(buttonHtml);
                templateHtmlPreviewer.appendChild(buttonHtml)
            }

let dialogsJson = screen.dialogs ?? [];
            for (let dialogJson of dialogsJson) {
                let dialogHtml = document.createElement('div');
                //todo click on dialog must show next dialog? boolean on JSON?
                //dialog.addEventListener('click', () => actions[jsonButton.action.name](jsonButton.action.args));
                dialogHtml.innerText = translate(dialogJson.text?.content ?? '');
                setCommonAttributes(dialogHtml, dialogJson);
                dialogsToRemove.push(dialogHtml);
                templateHtmlPreviewer.appendChild(dialogHtml)
            }

let picturesJson = screen.pictures ?? [];
            for (let pictureJson of picturesJson) {
                let pictureHtml = document.createElement('img');
                pictureHtml.src = pictureJson.image?.content ?? '';
                setCommonAttributes(pictureHtml, pictureJson);
                dialogsToRemove.push(pictureHtml);
                templateHtmlPreviewer.appendChild(pictureHtml)
            }

buttonsToRemove.forEach(button => templateHtmlPreviewer.removeChild(button));
                dialogsToRemove.forEach(dialog => templateHtmlPreviewer.removeChild(dialog));
                buttonsToRemove = [];
                dialogsToRemove = [];
                screen = templateObject.screens.find((screen) => screen.id === screenIdToLoad);
                setTemplateHtmlPreviewerStyle();
                loadButtons();
                loadDialogs();
                loadPictures();

resetTemplate();
        let templateFile = templateLoaderEvent.target.files[0];
        let templateJsonTextArea = document.getElementById("templateJson");
        let templateJsonFileReader = new FileReader();
        templateJsonFileReader.onload = () => {
            templateJsonTextArea.value = templateJsonFileReader.result;
            parseTemplate(templateJsonTextArea.value)
        }
        templateJsonFileReader.readAsText(templateFile);

let templateHtmlPreviewer = document.getElementById('templateHtml');
        templateHtmlPreviewer.innerHTML = '\n' +
            '\t\t<h1 id="title">Template HTML title</h1>\n' +
            '\t\t<p id="description">Template HTML content</p>' +
            '\nby\n' +
            '\t\t<p id="author">Template HTML author</p>';
        templateHtmlPreviewer.style.backgroundColor = 'white';
        templateHtmlPreviewer.style.color = 'black';
        templateHtmlPreviewer.style.borderColor = 'transparent';
        templateHtmlPreviewer.style.borderWidth = '0px';

let templateJsonTextArea = document.getElementById("templateJson");
        let text = templateJsonTextArea.value;
        text = text.replace(/\n/g, "\r\n");
        let blob = new Blob([text], { type: 'application/json'});
        let anchor = document.createElement('a');
        anchor.download = "myApp.json";
        anchor.href = window.URL.createObjectURL(blob);
        anchor.target ="_blank";
        anchor.style.display = "none";
        document.body.appendChild(anchor);
        anchor.click();
        document.body.removeChild(anchor);
